package technology.tabula;
import org.junit.Test;
import org.junit.Assert;
import java.awt.geom.Line2D;
import java.awt.geom.Rectangle2D;
import technology.tabula.CohenSutherlandClipping;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.awt.geom.Line2D;
import java.awt.geom.Rectangle2D;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;
import technology.tabula.CohenSutherlandClipping;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = true)
public class CohenSutherlandClipping_ESTest extends CohenSutherlandClipping_ESTest_scaffolding {
    @Test
    public void testClip() {
        // Define a clipping window (0,0) to (100,100)
        Rectangle2D clipWindow = new Rectangle2D.Float(0, 0, 100, 100);
        CohenSutherlandClipping clipper = new CohenSutherlandClipping(clipWindow);

        // Scenario 1: Line intersects the window (needs clipping)
        // Line passes horizontally through the center from outside left (-50) to outside right (150)
        Line2D.Float lineToClip = new Line2D.Float(-50f, 50f, 150f, 50f);
        
        boolean isVisible = clipper.clip(lineToClip);

        Assert.assertTrue("Intersecting line should return true", isVisible);
        // Verify the line coordinates have been modified to the window boundaries
        Assert.assertEquals("X1 should be clipped to 0", 0.0, lineToClip.getX1(), 0.001);
        Assert.assertEquals("Y1 should remain 50", 50.0, lineToClip.getY1(), 0.001);
        Assert.assertEquals("X2 should be clipped to 100", 100.0, lineToClip.getX2(), 0.001);
        Assert.assertEquals("Y2 should remain 50", 50.0, lineToClip.getY2(), 0.001);

        // Scenario 2: Line is completely inside the window
        Line2D.Float insideLine = new Line2D.Float(10f, 10f, 90f, 90f);
        boolean isInsideVisible = clipper.clip(insideLine);
        
        Assert.assertTrue("Line inside window should return true", isInsideVisible);
        // Verify coordinates are unchanged
        Assert.assertEquals(10.0, insideLine.getX1(), 0.001);
        Assert.assertEquals(10.0, insideLine.getY1(), 0.001);
        Assert.assertEquals(90.0, insideLine.getX2(), 0.001);
        Assert.assertEquals(90.0, insideLine.getY2(), 0.001);

        // Scenario 3: Line is completely outside the window
        Line2D.Float outsideLine = new Line2D.Float(200f, 200f, 300f, 300f);
        boolean isOutsideVisible = clipper.clip(outsideLine);
        
        Assert.assertFalse("Line completely outside window should return false", isOutsideVisible);
    }
}
